import java.util.*;

class Solution {
  public int maxSumRangeQuery(int[] nums, int[][] requests) {
    final long MOD = 1_000_000_007L;
    int[] diff = new int[nums.length + 1];
    for (int[] request : requests) {
      diff[request[0]]++;
      diff[request[1] + 1]--;
    }
    int[] frequency = new int[nums.length];
    int active = 0;
    for (int i = 0; i < nums.length; i++) {
      active += diff[i];
      frequency[i] = active;
    }
    Arrays.sort(nums);
    Arrays.sort(frequency);
    long result = 0;
    for (int i = 0; i < nums.length; i++) result = (result + (long) nums[i] * frequency[i]) % MOD;
    return (int) result;
  }
}
